client_script:
frappe.ready(() => {
    $('#user-input-form').on('submit', (e) => {
        e.preventDefault();

        // Get form data
        const form_data = {
            num_adults: $('#num_adults').val(),
            num_children: $('#num_children').val(),
            num_infants: $('#num_infants').val(),
            arrival_month: $('#arrival_month').val(),
            num_nights: $('#num_nights').val(),
            weekend: $('#weekend').is(':checked') ? 1 : 0,
            holiday: $('#holiday').is(':checked') ? 1 : 0,
            customer_origin: $('#customer_origin').val(),
            hotel_name: $('#hotel_name').val()
        };

        // Submit form data to the API
        frappe.call({
            method: 'hotel_recommendation_system.api.submit_user_info',
            args: form_data,
            callback: (response) => {
                if (response.message && response.message.message) {
                    frappe.msgprint(response.message.message);
                } else if (response.message && response.message.error) {
                    frappe.msgprint(response.message.error);
                }
            }
        });
    });
});
